#include "facts_data.hpp"

namespace nikos::facts::data {

const Fact kAnimalsFacts[kFactsPerCategory] = {
    {"animals-001", "Sen delfina", "Delfiny potrafią spać z jednym otwartym okiem. Odpoczywa wtedy tylko jedna połowa ich mózgu."},
    {"animals-002", "Taniec pszczół", "Pszczoły przekazują informacje o jedzeniu tańcem. Ruchy pokazują innym kierunek i odległość do pokarmu."},
    {"animals-003", "Pamięć wron", "Wrony potrafią zapamiętać twarz człowieka. W badaniach rozpoznawały osoby w maskach nawet po latach."},
    {"animals-004", "Ryba strzelczyk", "Ryba strzelczyk strąca owady strumieniem wody. Trafiony owad spada do wody i staje się zdobyczą."},
    {"animals-005", "Słonie słuchają stopami", "Słonie potrafią odbierać drgania gruntu stopami. Niskie pomruki innych słoni przenoszą się też przez ziemię."},
    {"animals-006", "Lot kolibra", "Kolibry potrafią latać do tyłu. Potrafią też zawisnąć w powietrzu jak helikopter."},
    {"animals-007", "Kompas żółwi morskich", "Żółwie morskie korzystają z ziemskiego pola magnetycznego. Pomaga im ono odnajdywać drogę podczas dalekich wędrówek."},
    {"animals-008", "Echolokacja nietoperzy", "Nietoperze potrafią namierzać owady samym dźwiękiem. Wysyłają piski i nasłuchują odbitego echa."},
    {"animals-009", "Elektryczny dziób dziobaka", "Dziobak zamyka oczy, uszy i nozdrza podczas nurkowania. Ofiary wykrywa dziobem wyczuwającym impulsy elektryczne."},
    {"animals-010", "Motyle smakują stopami", "Motyle potrafią smakować stopami. Tak sprawdzają, czy liść nadaje się do złożenia jaj."},
    {"animals-011", "Trzy serca ośmiornicy", "Ośmiornica ma trzy serca. Dwa pompują krew do skrzeli, trzecie do reszty ciała."},
    {"animals-012", "Gekon na suficie", "Gekon potrafi chodzić po gładkim suficie. Pomagają mu miliony maleńkich włosków na palcach."},
    {"animals-013", "Kostki wombata", "Wombaty pozostawiają odchody w kształcie kostek. Ich charakterystyczny kształt powstaje dzięki właściwościom ścian jelita."},
    {"animals-014", "Regeneracja aksolotla", "Aksolotl potrafi odtworzyć utraconą nogę. Regeneruje też fragmenty serca i rdzenia kręgowego."},
    {"animals-015", "Żołądek rozgwiazdy", "Rozgwiazda może trawić zdobycz poza własnym ciałem. Wysuwa żołądek na przykład do muszli małża."},
    {"animals-016", "Tata konik morski", "U koników morskich samiec nosi rozwijające się zarodki w torbie lęgowej. Po zakończeniu rozwoju wypuszcza z niej młode."},
    {"animals-017", "Pingwiny podczas zamieci", "Pingwiny cesarskie stoją ciasno razem podczas zamieci. Zamieniają się miejscami, by każdy mógł się ogrzać."},
    {"animals-018", "Królowa golców", "Golce piaskowe żyją w koloniach podobnych do mrowisk. Młode rodzi tylko jedna samica, zwana królową."},
    {"animals-019", "Dlaczego flamingi różowieją", "Flamingi nie rodzą się różowe. Różowieją dzięki barwnikom z glonów i drobnych skorupiaków."},
    {"animals-020", "Podstęp kukułki", "Kukułka podrzuca swoje jaja do cudzych gniazd. Jej pisklę potrafi wypchnąć z gniazda pozostałe jaja."},
    {"animals-021", "Prąd węgorza elektrycznego", "Węgorz elektryczny potrafi razić prądem. U niektórych gatunków wyładowanie sięga 860 woltów."},
    {"animals-022", "Cios krewetki modliszkowej", "Cios krewetki modliszkowej wytwarza pęcherzyki pary. Powstają, gdy gwałtownie spada ciśnienie wody."},
    {"animals-023", "Zamarzająca żaba", "Żaba leśna potrafi zamarznąć zimą i odżyć wiosną. Jej organizm wytwarza cukier chroniący komórki przed lodem."},
    {"animals-024", "Niesporczaki w kosmosie", "Niektóre niesporczaki przeżyły pobyt w kosmicznej próżni. Były odwodnione i niemal całkowicie nieaktywne."},
    {"animals-025", "Pomarańczowe zęby bobra", "Bobry mają pomarańczowe siekacze. Ich szkliwo zawiera żelazo, które je wzmacnia."},
    {"animals-026", "Oczy renifera zimą", "Zimą oczy reniferów odbijają światło na niebiesko. Latem ta sama warstwa w oku ma złotawy kolor."},
    {"animals-027", "Nielotna papuga kakapo", "Kakapo to papuga, która nie potrafi latać. Prowadzi nocny tryb życia i waży nawet 4 kg."},
    {"animals-028", "Spiżarnia dzierzby", "Dzierzby potrafią nabijać zdobycz na ciernie. Tak przechowują jedzenie na później."},
    {"animals-029", "Niebieskie skarby altannika", "Samiec altannika ozdabia swoją altankę niebieskimi przedmiotami. Zbiera pióra, kwiaty, a nawet nakrętki."},
    {"animals-030", "Jerzyk bez lądowania", "Jerzyki potrafią spędzić niemal 10 miesięcy bez lądowania. Na ziemię wracają głównie na czas lęgów."},
    {"animals-031", "Bąbelkowa pułapka humbaka", "Humbaki potrafią otoczyć ławicę ryb ścianą bąbelków. Tak zaganiają zdobycz w pułapkę."},
    {"animals-032", "Kamienie wydry morskiej", "Wydry morskie rozbijają muszle kamieniami. Robią to często, pływając na plecach."},
    {"animals-033", "Długowieczny rekin", "Rekin grenlandzki może żyć nawet kilkaset lat. Jego wiek szacuje się na podstawie soczewek oczu."},
    {"animals-034", "Ząb narwala", "Długi róg narwala w rzeczywistości jest zębem. U samców może osiągać niemal 3 metry."},
    {"animals-035", "Sen meduzy bez mózgu", "Meduzy Cassiopea zapadają w stan podobny do snu, choć nie mają mózgu. Wtedy wolniej pulsują i słabiej reagują na bodźce."},
    {"animals-036", "Mrówki hodujące grzyby", "Mrówki grzybiarki nie jedzą liści, które zbierają. Hodują na nich grzyby, którymi się żywią."},
    {"animals-037", "Żuki i Droga Mleczna", "Niektóre żuki gnojowe orientują się według Drogi Mlecznej. Pomaga im to toczyć kulki nawozu w prostej linii."},
    {"animals-038", "Pająki zjadają sieci", "Niektóre pająki zjadają własne sieci. Odzyskują w ten sposób materiał do budowy nowych."},
    {"animals-039", "Synchroniczne świetliki", "Pewne świetliki potrafią błyskać jednocześnie. Samce synchronizują swoje sygnały podczas godów."},
    {"animals-040", "Ślimak z chloroplastami", "Ślimak morski Elysia przechowuje części zjedzonych glonów. To chloroplasty, które nadal mogą prowadzić fotosyntezę."},
    {"animals-041", "Przezroczyste żaby", "Szklane żaby stają się bardziej przezroczyste podczas snu. Ukrywają wtedy większość czerwonych krwinek w wątrobie."},
    {"animals-042", "Jaszczurka strzela krwią", "Niektóre jaszczurki rogate strzelają krwią z oczu. W ten sposób odstraszają między innymi kojoty."},
    {"animals-043", "Skąd trucizna u żab", "Niektóre trujące żaby tracą toksyczność w hodowli. W naturze pozyskują truciznę ze zjadanych owadów."},
    {"animals-044", "Mroźny sen susła", "U susła arktycznego temperatura ciała może spaść poniżej zera. Podczas zimowego snu nie zamarzają jednak jego płyny ustrojowe."},
    {"animals-045", "Zmiana płci u błazenka", "Gdy samica błazenka zginie, samiec może zmienić płeć. Staje się wtedy nową samicą w grupie."},
    {"animals-046", "Koła rozdymki", "Samce pewnych rozdymek rysują koła na dnie morza. Wzory z piasku mają przyciągnąć samice."},
    {"animals-047", "Czarna skóra niedźwiedzia", "Niedźwiedź polarny ma czarną skórę. Jego sierść nie jest biała — włosy są pozbawione barwnika."},
    {"animals-048", "Niebieska krew skrzypłocza", "Skrzypłocz ma niebieską krew. Tlen przenosi w niej białko zawierające miedź."},
    {"animals-049", "Chemiczna broń chrząszcza", "Chrząszcz strzel łoskotnik broni się bardzo gorącą cieczą. Powstaje ona podczas reakcji chemicznej w jego odwłoku."},
    {"animals-050", "Diabeł kolczasty i woda", "Diabeł kolczasty to jaszczurka, która zbiera wodę z wilgotnego piasku. Rowki między łuskami prowadzą ją prosto do pyska."},
    {"animals-051", "Ryby wyszły na ląd", "Pierwsze czworonogi wyewoluowały z ryb mięśniopłetwych. Ich kończyny powstały z przekształconych płetw."},
    {"animals-052", "Ptaki są dinozaurami", "Współczesne ptaki należą do jednej z linii dinozaurów. Ich przodkami były opierzone teropody."},
    {"animals-053", "Wieloryby wróciły do wody", "Przodkowie wielorybów byli ssakami lądowymi. Ich potomkowie stopniowo przystosowali się do życia w morzu."},
    {"animals-054", "Koń miał więcej palców", "Dawni krewni koni mieli kilka palców u stóp. U dzisiejszych koni ciężar ciała spoczywa głównie na jednym."},
    {"animals-055", "Żywe skamieniałości?", "Skrzypłocze należą do bardzo starej linii zwierząt. Nie oznacza to, że przez miliony lat wcale się nie zmieniały."},
    {"animals-056", "Ślepe ryby jaskiniowe", "Niektóre ryby żyjące w jaskiniach utraciły oczy i pigment. Ich przodkowie żyli w oświetlonych wodach."},
    {"animals-057", "Długi język żyrafy", "Żyrafy mają chwytne, długie języki. Pomagają im zrywać liście nawet z kolczastych gałęzi."},
    {"animals-058", "Wyspy i gigantyzm", "Na wyspach niektóre małe gatunki z czasem osiągały wielkie rozmiary. To jedna z możliwych dróg ewolucji wyspowej."},
    {"animals-059", "Wyspy i karłowatość", "Izolowane populacje dużych zwierząt bywają mniejsze od lądowych krewnych. Przykładem były karłowate słonie."},
    {"animals-060", "Mimetyzm liści", "Niektóre owady przypominają liście kształtem i barwą. Kamuflaż utrudnia drapieżnikom ich zauważenie."},
    {"animals-061", "Motyle naśladują trujące", "Nietrujące motyle mogą przypominać gatunki niesmaczne dla drapieżników. Tak działa mimikra batesowska."},
    {"animals-062", "Barwy ostrzegawcze", "Jaskrawe kolory części zwierząt sygnalizują toksyczność lub niesmaczność. Drapieżniki mogą nauczyć się ich unikać."},
    {"animals-063", "Ośmiornice zmieniają barwy", "Komórki barwnikowe pozwalają ośmiornicom szybko zmieniać wygląd skóry. Służy to kamuflażowi i sygnalizacji."},
    {"animals-064", "Pszczoły widzą ultrafiolet", "Pszczoły widzą wzory ultrafioletowe na kwiatach. Dla ludzkiego oka te wzory pozostają niewidoczne."},
    {"animals-065", "Kolce jeżozwierza", "Kolce jeżozwierza to zmodyfikowane włosy. Służą do obrony przed napastnikami."},
    {"animals-066", "Zęby bez końca", "Siekacze gryzoni rosną przez całe życie. Ścierają się podczas gryzienia twardych materiałów."},
    {"animals-067", "Jadowite ssaki", "Nie tylko węże bywają jadowite. Samce dziobaków mają ostrogi połączone z gruczołami jadowymi."},
    {"animals-068", "Tlen w lodowatej wodzie", "Ryby lodowe z Antarktyki mogą nie mieć hemoglobiny. Ich krew jest przez to wyjątkowo blada."},
    {"animals-069", "Samce rajskich ptaków", "Samce wielu rajskich ptaków wykonują złożone tańce godowe. Dobór płciowy wpływa na ich wygląd."},
    {"animals-070", "Szybki sokół", "Sokół wędrowny podczas nurkowania może przekraczać 300 km/h. To jeden z najszybszych ruchów w świecie zwierząt."},
    {"animals-071", "Mrówki odnajdują dom", "Niektóre pustynne mrówki szacują przebytą drogę. Wykorzystują także położenie Słońca."},
    {"animals-072", "Krokodyle i ptaki", "Krokodyle są bliżej spokrewnione z ptakami niż z jaszczurkami. Obie grupy należą do archozaurów."},
    {"animals-073", "Zęby rekinów", "Rekiny wymieniają zęby przez całe życie. Nowe zęby przesuwają się na miejsce utraconych."},
    {"animals-074", "Zmienna długość dzioba", "Kształty dziobów zięb z Galápagos różnią się zależnie od pokarmu. To klasyczny przykład doboru naturalnego."},
    {"animals-075", "Molekularny zegar", "Zmiany w DNA pomagają szacować czas rozdzielenia linii ewolucyjnych. Wyniki zależą od kalibracji i modelu."},
    {"animals-076", "Mrówki budują tratwy", "Mrówki ogniste potrafią łączyć ciała w pływające tratwy. Tak całe kolonie mogą przetrwać powódź."},
    {"animals-077", "Krewetka czyści ryby", "Niektóre krewetki usuwają pasożyty z ciał większych ryb. To przykład współpracy między gatunkami."},
    {"animals-078", "Delfiny mają gwizdy", "Delfiny butlonose używają charakterystycznych gwizdów kontaktowych. Mogą dzięki nim rozpoznawać konkretne osobniki."},
    {"animals-079", "Pszczoły uczą się", "Trzmiele mogą nauczyć się nowych czynności, obserwując inne trzmiele. To przykład społecznego uczenia się u owadów."},
    {"animals-080", "Słonie pocieszają?", "Słonie potrafią zbliżać się do pobudzonych członków stada. Badacze analizują dotyk i głosy jako formy reakcji społecznej."},
    {"animals-081", "Morsy używają wąsów", "Wibrysy morsa pomagają wykrywać pokarm na dnie morza. Są bardzo czułym narządem dotyku."},
    {"animals-082", "Ryba zmienia kolor", "Niektóre ryby rafowe szybko zmieniają barwy. Służą one między innymi komunikacji i kamuflażowi."},
    {"animals-083", "Ruchome wzory mątwy", "Mątwy potrafią przesuwać po skórze jasne i ciemne pasma. Wykorzystują takie wzory między innymi podczas polowania."},
    {"animals-084", "Pisklę słyszy wcześniej", "Niektóre ptaki reagują na dźwięki jeszcze wewnątrz jaja. Pozwala im to rozpoznawać sygnały rodziców."},
    {"animals-085", "Nietoperz zapyla kwiaty", "W tropikach wiele roślin jest zapylanych przez nietoperze. Część kwiatów otwiera się lub pachnie najmocniej nocą."},
    {"animals-086", "Nocne oko kota", "Kot ma błonę odblaskową za siatkówką oka. Pomaga ona wykorzystać słabe światło."},
    {"animals-087", "Kangur i ruch", "Kangury wykorzystują sprężyste ścięgna podczas skoków. Dzięki temu szybkie poruszanie może być oszczędne energetycznie."},
    {"animals-088", "Oddychające kopce termitów", "W kopcach niektórych termitów istnieje sieć kanałów wentylacyjnych. Pomaga ona wymieniać powietrze dzięki zmianom temperatury."},
    {"animals-089", "Sępy trawią padlinę", "Bardzo kwaśny żołądek sępów pomaga rozkładać pokarm. Ptaki te odgrywają ważną rolę w usuwaniu padliny."},
    {"animals-090", "Dlaczego zebry w paski", "Badania wskazują, że pasy zebr mogą ograniczać lądowanie gryzących much. Nie jest to jedyne proponowane wyjaśnienie ich ubarwienia."},
    {"animals-091", "Głosy orek", "Różne grupy orek mają charakterystyczne zestawy odgłosów. Część wzorców jest przekazywana między pokoleniami."},
    {"animals-092", "Żaby z opieką rodziców", "Niektóre żaby przenoszą kijanki na grzbiecie. U części gatunków rodzice dostarczają im też pokarm."},
    {"animals-093", "Koliber i pamięć", "Kolibry potrafią zapamiętywać położenie odwiedzonych kwiatów. Pomaga im to wracać po nektar we właściwym czasie."},
    {"animals-094", "Wspólna obrona surykatek", "Surykatki wystawiają czujki podczas żerowania. Alarmy ostrzegają grupę przed drapieżnikami."},
    {"animals-095", "Kraby ozdabiają pancerz", "Niektóre kraby mocują do ciała gąbki lub glony. Taka osłona może utrudniać ich zauważenie."},
    {"animals-096", "Ślimak buduje muszlę", "Ślimaki wytwarzają muszle z minerałów i białek. Muszla rośnie wraz ze zwierzęciem, ale nie jest osobnym organizmem."},
    {"animals-097", "Język dzięcioła", "Aparat gnykowy dzięciołów może sięgać daleko wokół czaszki. Pomaga wysuwać i podtrzymywać długi język."},
    {"animals-098", "Samice hien rządzą", "U hien cętkowanych samice zwykle zajmują wyższą pozycję niż samce. Hierarchia wpływa na dostęp do pokarmu."},
    {"animals-099", "Ryby śpią inaczej", "Ryby mają okresy spoczynku, choć zwykle nie zamykają oczu. Ich sposób odpoczynku różni się od snu ssaków."},
    {"animals-100", "Kałamarnica i atrament", "Wiele głowonogów wyrzuca chmurę atramentu, gdy grozi im niebezpieczeństwo. Może ona odwrócić uwagę drapieżnika."},
};

}  // namespace nikos::facts::data
